# Generated by specmill; client-owned HTTP runtime.
api_request <- function(method, path, path_params, query, body, headers = list(), query_serialization = list(), body_media = 'application/json', auth = NULL, batch = list(), parameter_serialization = list(), cookies = list()) {
  encode_parameter <- function(value, p) {
    if (is.null(value)) {
      if (isTRUE(p$required)) stop('Required parameter: ', p$name)
      return(character())
    }
    type <- p$schema$type
    style <- p$style
    explode <- isTRUE(p$explode)
    scalar <- function(x, schema) {
      valid <- !is.object(x) && is.null(dim(x)) && is.null(names(x)) && length(x) == 1L && !anyNA(x) &&
        (is.character(x) || is.logical(x) || (is.numeric(x) && is.finite(x)))
      if (valid && !is.null(schema$type)) valid <- switch(schema$type,
        string = is.character(x), boolean = is.logical(x),
        number = is.numeric(x), integer = is.numeric(x) && x == trunc(x), FALSE)
      if (!valid) stop('Parameter must contain finite, non-null scalars of its declared type: ', p$name)
      if (is.logical(x)) if (x) 'true' else 'false' else as.character(x)
    }
    if (is.object(value) || !is.null(dim(value))) stop('Parameter must be a plain vector or list: ', p$name)
    keys <- names(value)
    if (identical(type, 'object')) {
      if (!is.list(value) || (length(value) && is.null(keys)) || anyNA(keys) || anyDuplicated(keys) || any(!nzchar(keys))) stop('Object parameter must be a uniquely named list: ', p$name)
      if (!all(unlist(p$schema$required) %in% keys)) stop('Missing required parameter fields: ', p$name)
      if (isFALSE(p$schema$additionalProperties) && length(setdiff(keys, names(p$schema$properties)))) stop('Unknown parameter fields: ', p$name)
      values <- vapply(seq_along(value), function(i) {
        child <- p$schema$properties[[keys[[i]]]]
        if (is.null(child) && is.list(p$schema$additionalProperties)) child <- p$schema$additionalProperties
        scalar(value[[i]], child)
      }, character(1))
    } else if (identical(type, 'array')) {
      if (!is.null(keys) || !(is.atomic(value) || is.list(value))) stop('Array parameter must be an unnamed vector or list: ', p$name)
      if ((!is.null(p$schema$minItems) && length(value) < p$schema$minItems) || (!is.null(p$schema$maxItems) && length(value) > p$schema$maxItems)) stop('Invalid parameter array length: ', p$name)
      values <- vapply(value, scalar, character(1), schema = p$schema$items)
    } else values <- scalar(value, p$schema)
    # URI templates do not define a distinct representation for an empty list/map.
    if (type %in% c('array', 'object') && !length(values)) stop('Empty parameter containers cannot be encoded unambiguously: ', p$name)
    if (p$location == 'header') {
      if (any(grepl('[\r\n]', c(keys, values)))) stop('Newlines are forbidden in header parameters')
      separator <- if (is.null(p$collection_format)) ',' else switch(p$collection_format, ssv = ' ', tsv = '\t', pipes = '|', ',')
      if (type %in% c('array', 'object') &&
          (any(grepl(separator, c(keys, values), fixed = TRUE)) ||
           (type == 'object' && explode && any(grepl('=', c(keys, values), fixed = TRUE))))) stop('Header parameter values contain serialization delimiters')
      encode <- identity
    } else {
      separator <- if (identical(p$collection_format, 'tsv')) '\t' else if (style == 'spaceDelimited' || identical(p$collection_format, 'ssv')) ' ' else NULL
      if (!explode && !is.null(separator) && any(grepl(separator, c(keys, values), fixed = TRUE))) stop('Parameter values contain an ambiguous whitespace delimiter')
      encode <- function(x) utils::URLencode(enc2utf8(x), reserved = TRUE, repeated = TRUE)
    }
    values <- vapply(values, encode, character(1), USE.NAMES = FALSE)
    keys <- vapply(keys, encode, character(1), USE.NAMES = FALSE)
    name <- encode(p$name)
    delimiter <- if (!is.null(p$collection_format)) switch(p$collection_format, csv = ',', ssv = '%20', tsv = '%09', pipes = '|', multi = ',') else switch(style, spaceDelimited = '%20', pipeDelimited = '|', ',')
    if (p$location == 'header') delimiter <- if (!is.null(p$collection_format)) switch(p$collection_format, ssv = ' ', tsv = '\t', pipes = '|', ',') else ','
    flat <- if (identical(type, 'object')) as.vector(rbind(keys, values)) else values
    if (p$location %in% c('query', 'cookie')) {
      if (style == 'deepObject') return(paste0(name, '[', keys, ']=', values))
      if (explode && identical(type, 'object')) return(paste0(keys, '=', values))
      if (explode && identical(type, 'array')) return(paste0(name, '=', values))
      return(paste0(name, '=', paste(flat, collapse = delimiter)))
    }
    if (style == 'matrix') {
      if (explode && identical(type, 'object')) return(paste0(';', paste0(keys, '=', values, collapse = ';')))
      if (explode && identical(type, 'array')) return(paste0(';', paste0(name, '=', values, collapse = ';')))
      return(paste0(';', name, if (length(flat) == 1L && flat == '') '' else paste0('=', paste(flat, collapse = ','))))
    }
    if (identical(type, 'object') && explode) flat <- paste0(keys, '=', values)
    if (style == 'label' && explode) {
      # Escape literal dots before adding label separators.
      flat <- gsub('.', '%2E', flat, fixed = TRUE)
      delimiter <- '.'
    }
    paste0(if (style == 'label') '.' else '', paste(flat, collapse = delimiter))
  }
  encoded_query <- list()
  encoded_cookies <- list()
  for (p in parameter_serialization) {
    values <- switch(p$location, path = path_params, query = query, header = headers, cookie = cookies)
    encoded <- encode_parameter(values[[p$name]], p)
    if (p$location == 'path') {
      path <- gsub(paste0('{', p$name, '}'), encoded, path, fixed = TRUE)
      path_params[p$name] <- NULL
    } else if (p$location == 'query') {
      encoded_query[[length(encoded_query) + 1L]] <- encoded
      query[p$name] <- NULL
    } else if (p$location == 'header') {
      headers[p$name] <- if (length(encoded)) list(encoded) else list(NULL)
    } else encoded_cookies[[length(encoded_cookies) + 1L]] <- encoded
  }
  for (limit in batch) {
    if (!is.numeric(limit) || length(limit) != 1L || is.na(limit) || !is.finite(limit) || limit < 1 || limit != floor(limit)) stop('Batch limits must be positive integers')
  }
  if (!is.null(batch$max_items) && !is.null(body)) {
    if (!is.list(body) || !is.null(names(body))) stop('Batch body must be an unnamed list of items')
    if (length(body) > batch$max_items) stop('Batch exceeds max_items (', batch$max_items, '); split the input into smaller requests')
  }
  for (name in names(path_params)) {
    path <- gsub(paste0('{', name, '}'), utils::URLencode(as.character(path_params[[name]]), reserved = TRUE), path, fixed = TRUE)
  }
  request <- httr2::request(BASE_URL)
  request <- httr2::req_method(request, method)
  query <- Filter(Negate(is.null), query)
  for (name in names(query)) {
    serialization <- query_serialization[[name]]
    if (is.null(serialization)) serialization <- 'error'
    if (name %in% names(query_serialization)) {
      if (!serialization %in% c('comma', 'explode')) stop('Unsupported query array serialization')
      if (!is.character(query[[name]]) || anyNA(query[[name]])) stop('Query array must be a character vector without missing values')
      encoded_query[[length(encoded_query) + 1L]] <- encode_parameter(query[[name]], list(name = name, location = 'query', schema = list(type = 'array', items = list(type = 'string')), style = 'form', explode = serialization == 'explode'))
    } else request <- do.call(httr2::req_url_query, c(list(request, .multi = serialization), query[name]))
  }
  headers <- Filter(Negate(is.null), headers)
  if (length(headers)) request <- do.call(httr2::req_headers, c(list(request), headers))
  suffix <- if (grepl('?', request$url, fixed = TRUE)) sub('^[^?]*', '', request$url) else ''
  request <- httr2::req_url(request, paste0(sub('/+$', '', BASE_URL), '/', sub('^/+', '', path), suffix))
  encoded_query <- unlist(encoded_query, use.names = FALSE)
  encoded_cookies <- unlist(encoded_cookies, use.names = FALSE)
  if (length(encoded_cookies)) {
    prior <- request$headers[['Cookie']]
    request <- httr2::req_headers(request, Cookie = paste(c(prior, encoded_cookies), collapse = '; '))
  }
  if (!is.null(body)) {
    if (!is.null(batch$max_bytes)) {
      bytes <- if (identical(body_media, 'application/json')) {
        charToRaw(enc2utf8(as.character(jsonlite::toJSON(body, auto_unbox = TRUE, null = 'null', digits = 22))))
      } else body
      if (!is.raw(bytes)) stop('Binary body must be a raw vector')
      if (length(bytes) > batch$max_bytes) stop('Batch exceeds max_bytes (', batch$max_bytes, ')')
      request <- httr2::req_body_raw(request, bytes, type = body_media)
    } else
    if (identical(body_media, 'application/octet-stream')) {
      if (!is.raw(body)) stop('Binary body must be a raw vector')
      request <- httr2::req_body_raw(request, body, type = body_media)
    } else if (identical(body_media, 'application/json')) {
      request <- httr2::req_body_json(request, body, auto_unbox = TRUE, null = 'null')
    } else stop('Unsupported request body media type')
  }
  if (!is.null(auth)) request <- api_auth(request, auth)
  if (length(encoded_cookies)) request <- httr2::req_headers(request, .redact = 'Cookie')
  # Append encoded tokens last: query authentication must not decode/re-encode them.
  if (length(encoded_query)) request <- httr2::req_url(request, paste0(request$url, if (grepl('?', request$url, fixed = TRUE)) '&' else '?', paste(encoded_query, collapse = '&')))
  response <- httr2::req_perform(request)
  if (!httr2::resp_has_body(response)) return(NULL)
  bytes <- httr2::resp_body_raw(response)
  if (!length(bytes)) return(NULL)
  media <- httr2::resp_header(response, 'content-type')
  if (is.null(media)) media <- ''
  media <- tolower(sub(';.*$', '', media))
  if (grepl('(/json|\\+json)$', media)) return(jsonlite::fromJSON(httr2::resp_body_string(response), simplifyVector = FALSE))
  if (startsWith(media, 'text/') || media == 'image/svg+xml') return(httr2::resp_body_string(response))
  bytes
}
